import axios from "axios";

const API = axios.create({
  baseURL: "http://127.0.0.1:5000",
});


// 🔐 AUTH ===============================

// ✅ LOGIN
export const loginUser = (data) =>
  API.post("/auth/login", data);


// 📊 DASHBOARD ===========================

export const getDashboard = (token) =>
  API.get("/admin/dashboard", {
    headers: { Authorization: token }
  });


// 📢 NOTICES =============================

export const getNotices = () =>
  API.get("/admin/notices");

export const addNotice = (data, token) =>
  API.post("/admin/add-notice", data, {
    headers: { Authorization: token }
  });

export const deleteNotice = (id, token) =>
  API.delete(`/admin/delete-notice/${id}`, {
    headers: { Authorization: token }
  });


// 📚 STUDY ===============================

export const getStudy = () =>
  API.get("/admin/study");

export const addStudy = (data, token) =>
  API.post("/admin/add-study", data, {
    headers: { Authorization: token }
  });


// 📁 PDF UPLOAD ==========================

export const uploadPDF = (file, token) => {
  const formData = new FormData();
  formData.append("file", file);

  return API.post("/admin/upload-pdf", formData, {
    headers: {
      Authorization: token,
      "Content-Type": "multipart/form-data"
    }
  });
};


// 💬 CHATBOT =============================

export const sendMessage = (message) =>
  API.post("/chat", { message });


// 🧠 OPTIONAL CHAT HELPER

export const chatBotAPI = {
  send: (message) => API.post("/chat", { message }),
};
